export const ANDROID_ZIP_NAME = "Ash-Android-Studio.zip";
export const ANDROID_ZIP_BYTES = 54238;
export const ANDROID_ZIP_BASE64 =
  "";

export function zipBytes(): Uint8Array {
  const binary = atob(ANDROID_ZIP_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

export const MAC_DECODE_COMMAND = `pbpaste | base64 -D > ~/Downloads/${ANDROID_ZIP_NAME}`;

export async function downloadAndroidProject(): Promise<
  "saved" | "cancelled" | "blocked"
> {
  const bytes = zipBytes();
  const blob = new Blob([bytes.buffer as ArrayBuffer], {
    type: "application/octet-stream",
  });

  const picker = (
    window as Window & {
      showSaveFilePicker?: (opts: {
        suggestedName: string;
        types: { description: string; accept: Record<string, string[]> }[];
      }) => Promise<{
        createWritable: () => Promise<{
          write: (data: Blob) => Promise<void>;
          close: () => Promise<void>;
        }>;
      }>;
    }
  ).showSaveFilePicker;

  if (typeof picker === "function") {
    try {
      const handle = await picker({
        suggestedName: ANDROID_ZIP_NAME,
        types: [
          {
            description: "ZIP archive",
            accept: { "application/octet-stream": [".zip"] },
          },
        ],
      });
      const writable = await handle.createWritable();
      await writable.write(blob);
      await writable.close();
      return "saved";
    } catch (error) {
      if (error instanceof DOMException && error.name === "AbortError") {
        return "cancelled";
      }
    }
  }

  try {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = ANDROID_ZIP_NAME;
    a.rel = "noopener";
    document.body.appendChild(a);
    a.click();
    a.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 4000);
    return "saved";
  } catch {
    return "blocked";
  }
}

export async function copyAndroidProjectBase64(): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(ANDROID_ZIP_BASE64);
    return true;
  } catch {
    return false;
  }
}

